typedef unsigned int u32;
typedef unsigned char u8;
#define R(a) (*(volatile u32 *)(a))
#define FB R(0x10006000u)
#define SLOT R(0x10006004u)
#define STATUS R(0x10006008u)
#define FRAMES R(0x1000601cu)
#define HEART R(0x10004000u)
static volatile u32 * const palette=(volatile u32 *)0x10006400u;
static const unsigned short colors[8]={0,0xf00,0x0f0,0x00f,0xfff,0xff0,0x0ff,0xf0f};
// All framebuffer data is generated by RV32I firmware, no hardware pattern source.
static u32 pixel(u32 x,u32 y,u32 rx,u32 ry) {
 u32 p;
 if(y<64) p=x<64?1:x<128?2:x<192?3:x<256?4:0;
 else if(y<128)p=((x>>4)^(y>>4))&1?4:0;
 else p=3;
 if(x==y || x==319-y)p=5;
 if(x>=rx && x<rx+24 && y>=ry && y<ry+16)p=6;
 return p;
}
static void draw(u32 slot,u32 rx,u32 ry,u32 count,u32 hb) {
 volatile u32 *dst=(volatile u32 *)(slot?0x20010000u:0x20000000u);
 for(u32 y=0;y<200;y++)for(u32 x=0;x<320;x+=4) {
  u32 v=0;for(u32 b=0;b<4;b++)v|=pixel(x+b,y,rx,ry)<<(b<<3);
  *dst++=v;
 }
 // Photo-readable F(frame), H(heartbeat), U(underflow) fields.
 static const unsigned short font[16]={0x7b6f,0x2c97,0x73e7,0x73cf,0x5bc9,0x79cf,0x79ef,0x7249,0x7bef,0x7bcf,0x7bed,0x6bae,0x7927,0x6b6e,0x79a7,0x79a4};
 u32 values[3];values[0]=count;values[1]=hb;values[2]=R(0x1000600cu);
 volatile u8 *bytes=(volatile u8 *)(slot?0x20010000u:0x20000000u);
 for(u32 field=0;field<3;field++)for(u32 digit=0;digit<9;digit++) {
  u32 bits=digit?font[(values[field]>>((8-digit)*4))&15u]:field==0?0x7b24u:field==1?0x5bedu:0x5b6fu;
  for(u32 y=0;y<10;y++)for(u32 x=0;x<8;x++) {
   u32 ink=x<6 && ((bits>>(14-(y>>1)*3-(x>>1)))&1u);
   bytes[(166+field*11+y)*320+8+digit*8+x]=ink?(field==2?1:4):0;
  }
 }
}
int main(void) {
 for(u32 i=0;i<256;i++)palette[i]=colors[i&7];
 u32 rx=144,ry=144,hb=1;
 draw(0,rx,ry,0,hb);HEART=hb;
 SLOT=0;FB=1;R(0x10004008u)=1;
#ifdef SIM_STATIC_IMAGE
 for(;;){HEART=++hb;R(0x20020000u)=hb;}
#else
 u32 slot,view=1;
 while(!(STATUS&1u)){}
 for(;;) {
  slot=((STATUS>>1)&1u)^1u;
  u32 keys=R(0x1000200cu);
  while(R(0x10002004u)&0x100u){u32 event=R(0x10002000u);if(event==0x80000106u){view^=1u;FB=view;R(0x10004008u)=view;}}
  if((keys&1u)&&ry>130)ry-=2;
  if((keys&2u)&&ry<162)ry+=2;
  if((keys&4u)&&rx>2)rx-=2;
  if((keys&8u)&&rx<290)rx+=2;
  if(!(keys&15u)){rx+=2;if(rx>290)rx=2;}
  draw(slot,rx,ry,FRAMES,++hb);HEART=hb;
  R(0x10004014u)=R(0x1000600cu);R(0x10004010u)=R(0x10006010u);
  SLOT=slot;
  while(((STATUS>>1)&1u)!=slot){}
 }
#endif
}
